import React, {useEffect, useState} from 'react';
import {
	AbsoluteFill,
	continueRender,
	delayRender,
	Easing,
	interpolate,
	useCurrentFrame,
	useVideoConfig,
} from 'remotion';

/* ------------------------------------------------------------------ *
 *  PREMIUM END CARD — chroma-key outro template
 *  1920x1080 | 60fps | 15s
 *
 *  The three placeholder panels are pure #00FF00 and are composited
 *  LAST, above the vignette and the grain, so nothing tints or
 *  textures them. That is what keeps them keyable: a spill of grain or
 *  a vignette gradient across the green is exactly what makes a key
 *  tear at the edges. Frames, corner brackets and labels all sit
 *  outside the fill for the same reason.
 * ------------------------------------------------------------------ */

const FONT = 'InterEnd';
const F5 = '';
const F7 = '';
const F8 = '';
let fontRequested = false;
const ensureFont = () => {
	if (fontRequested || typeof document === 'undefined') return;
	fontRequested = true;
	const el = document.createElement('style');
	const face = (w: number, b: string) =>
		"@font-face{font-family:'" + FONT + "';font-style:normal;font-weight:" + w +
		';font-display:block;src:url(data:font/woff2;base64,' + b + ") format('woff2');}";
	el.textContent = face(500, F5) + face(700, F7) + face(800, F8);
	document.head.appendChild(el);
};

const W = 1920;
const H = 1080;
const TAU = Math.PI * 2;

/* premium palette — graphite and champagne */
const GOLD = '#E4C68C';
const GOLD_HI = '#F7E7C4';
const GOLD_D = '#8C7444';
const INK = '#F4F1EA';
const DIM = '#96907F';
const KEY = '#00FF00';

/* layout: the three panels are one centred group */
const MW = 1040;
const MH = 585;
const RW = 473;
const RH = 266;
const GAPX = 70;
/* enough gap for the second panel's label to clear the one above it */
const GAPY = 53;
const GX = (W - (MW + GAPX + RW)) / 2;
const GY = 292;
const RX = GX + MW + GAPX;

let _s = 0x2c7fa155 >>> 0;
const rr = () => {
	_s = (Math.imul(_s, 1664525) + 1013904223) >>> 0;
	return _s / 4294967296;
};

const DUST = Array.from({length: 110}, () => ({
	x: rr() * W,
	y: rr() * H,
	r: 0.6 + Math.pow(rr(), 2.2) * 3.2,
	o: 0.1 + rr() * 0.5,
	ax: 14 + rr() * 40,
	ay: 10 + rr() * 34,
	f1: 1 + Math.floor(rr() * 2),
	f2: 1 + Math.floor(rr() * 2),
	p1: rr(),
	p2: rr(),
	tf: 1 + Math.floor(rr() * 3),
	tp: rr(),
}));

const EASE = Easing.bezier(0.16, 0.84, 0.24, 1);
const EASE_S = Easing.bezier(0.34, 1.2, 0.4, 1);

/* corner brackets, drawn outside the keyed fill */
const Corner: React.FC<{w: number; h: number; s: number; o: number}> = ({w, h, s, o}) => (
	<svg width={w + 60} height={h + 60} style={{position: 'absolute', left: -30, top: -30, pointerEvents: 'none'}}>
		{[
			[16, 16, 1, 1],
			[w + 44, 16, -1, 1],
			[16, h + 44, 1, -1],
			[w + 44, h + 44, -1, -1],
		].map((q, i) => (
			<path
				key={i}
				d={
					'M' + (q[0] + q[2] * s) + ' ' + q[1] + 'H' + q[0] + 'V' + (q[1] + q[3] * s)
				}
				stroke={GOLD}
				strokeWidth={2}
				fill="none"
				opacity={o}
			/>
		))}
	</svg>
);

export const Motion: React.FC = () => {
	const frame = useCurrentFrame();
	const {fps} = useVideoConfig();
	const t = frame / fps;
	const u = frame / 900;

	const [fh] = useState(() => delayRender('end-font'));
	useEffect(() => {
		let done = false;
		const fin = () => {
			if (done) return;
			done = true;
			continueRender(fh);
		};
		ensureFont();
		const id = setTimeout(fin, 2500);
		Promise.all([
			document.fonts.load('500 16px ' + FONT),
			document.fonts.load('700 16px ' + FONT),
			document.fonts.load('800 62px ' + FONT),
		])
			.then(fin)
			.catch(fin);
		return () => clearTimeout(id);
	}, [fh]);

	const at = (s: number, d: number, e = EASE) =>
		interpolate(t, [s, s + d], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: e});

	/* entrance choreography */
	const bg = at(0, 0.7);
	const tTitle = at(0.18, 0.85);
	const tRule = at(0.42, 0.7);
	const tSub = at(0.95, 0.7);
	const tPill = at(1.2, 0.6, EASE_S);
	const tMain = at(0.34, 0.72);
	const tR1 = at(0.58, 0.66);
	const tR2 = at(0.74, 0.66);
	const tMeta = at(1.35, 0.7);

	/* ambient */
	const breathe = 0.5 + 0.5 * Math.sin(TAU * u * 2);
	const sweep = ((t * 0.16) % 1) * 2.6 - 0.8;

	const panel = (
		x: number,
		y: number,
		w: number,
		h: number,
		p: number,
		label: string,
		key: string
	) => {
		if (p <= 0.001) return null;
		const sc = 0.955 + 0.045 * p;
		return (
			<div
				key={key}
				style={{
					position: 'absolute',
					left: x,
					top: y,
					width: w,
					height: h,
					transform: 'scale(' + sc.toFixed(4) + ')',
					transformOrigin: '50% 50%',
					opacity: Math.min(1, p * 1.6),
				}}
			>
				{/* soft bed glow — sits UNDER the fill, never over it */}
				<div
					style={{
						position: 'absolute',
						left: -30,
						top: -30,
						width: w + 60,
						height: h + 60,
						background:
							'radial-gradient(60% 60% at 50% 50%, rgba(228,198,140,0.18), rgba(228,198,140,0) 72%)',
						filter: 'blur(16px)',
					}}
				/>
				{/* frame */}
				<div
					style={{
						position: 'absolute',
						left: -10,
						top: -10,
						width: w + 20,
						height: h + 20,
						border: '1.5px solid rgba(228,198,140,0.5)',
						boxShadow: '0 0 34px rgba(228,198,140,0.14)',
					}}
				/>
				{/* the keyable fill: flat, opaque, nothing layered on top */}
				<div
					style={{
						position: 'absolute',
						left: 0,
						top: 0,
						width: w,
						height: h,
						backgroundColor: KEY,
						clipPath: 'inset(0 ' + ((1 - p) * 100).toFixed(2) + '% 0 0)',
					}}
				/>
				<Corner w={w} h={h} s={Math.min(30, 30 * p)} o={0.9} />
				<div
					style={{
						position: 'absolute',
						left: 0,
						top: -34,
						fontSize: 12.5,
						fontWeight: 700,
						letterSpacing: 4.2,
						color: GOLD,
						opacity: Math.max(0, p * 1.4 - 0.4),
					}}
				>
					{label}
				</div>
			</div>
		);
	};

	return (
		<AbsoluteFill style={{backgroundColor: '#08080B', fontFamily: FONT}}>
			{/* ================= premium ground ================= */}
			<AbsoluteFill
				style={{
					background:
						'radial-gradient(88% 96% at 50% 42%, #191922 0%, #101016 42%, #0A0A0E 74%, #060608 100%)',
					opacity: bg,
				}}
			/>
			<AbsoluteFill
				style={{
					background:
						'radial-gradient(46% 52% at 18% 84%, rgba(228,198,140,' + (0.1 + 0.03 * breathe).toFixed(3) +
						') 0%, rgba(160,130,80,0.03) 44%, rgba(60,48,26,0) 74%)',
					opacity: bg,
				}}
			/>
			<AbsoluteFill
				style={{
					background:
						'radial-gradient(40% 46% at 86% 12%, rgba(150,180,230,0.07) 0%, rgba(80,100,150,0.02) 50%, rgba(0,0,0,0) 78%)',
					opacity: bg,
				}}
			/>
			<AbsoluteFill style={{opacity: 0.5 * bg}}>
				<svg width={W} height={H}>
					<defs>
						<pattern id="fine" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(35)">
							<path d="M0 0V7" stroke="rgba(228,198,140,0.045)" strokeWidth="1" />
						</pattern>
					</defs>
					<rect width={W} height={H} fill="url(#fine)" />
				</svg>
			</AbsoluteFill>

			{/* dust */}
			<AbsoluteFill style={{opacity: bg}}>
				<svg width={W} height={H}>
					{DUST.map((d, i) => (
						<circle
							key={i}
							cx={d.x + d.ax * Math.sin(TAU * (u * d.f1 + d.p1))}
							cy={d.y + d.ay * Math.cos(TAU * (u * d.f2 + d.p2))}
							r={d.r}
							fill={GOLD_HI}
							opacity={d.o * (0.45 + 0.55 * Math.sin(TAU * (u * d.tf + d.tp)))}
						/>
					))}
				</svg>
			</AbsoluteFill>

			{/* slow specular sweep */}
			<AbsoluteFill
				style={{
					background:
						'linear-gradient(104deg, rgba(255,255,255,0) ' + ((sweep - 0.18) * 100).toFixed(1) +
						'%, rgba(255,246,228,0.045) ' + (sweep * 100).toFixed(1) +
						'%, rgba(255,255,255,0) ' + ((sweep + 0.18) * 100).toFixed(1) + '%)',
					opacity: bg,
					pointerEvents: 'none',
				}}
			/>

			{/* ================= grade (kept off the key) ================= */}
			<AbsoluteFill
				style={{
					background:
						'radial-gradient(84% 88% at 50% 46%, rgba(0,0,0,0) 40%, rgba(6,6,9,0.5) 76%, rgba(3,3,5,0.95) 100%)',
					pointerEvents: 'none',
				}}
			/>
			<AbsoluteFill style={{opacity: 0.05, mixBlendMode: 'overlay', pointerEvents: 'none'}}>
				<svg width={W} height={H}>
					<filter id="grain41">
						<feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={(frame % 12) + 1} />
					</filter>
					<rect width={W} height={H} filter="url(#grain41)" />
				</svg>
			</AbsoluteFill>

			{/* ================= type ================= */}
			<div
				style={{
					position: 'absolute',
					left: 0,
					top: 128,
					width: W,
					textAlign: 'center',
					opacity: tTitle,
					transform: 'translateY(' + ((1 - tTitle) * 22).toFixed(1) + 'px)',
				}}
			>
				<div
					style={{
						fontSize: 13,
						fontWeight: 700,
						letterSpacing: 7.5,
						color: GOLD,
						marginBottom: 20,
						opacity: tTitle,
					}}
				>
					
				</div>
				<div
					style={{
						fontSize: 62,
						fontWeight: 500,
						letterSpacing: (26 - 16 * tTitle).toFixed(2) + 'px',
						color: INK,
						lineHeight: '68px',
						textIndent: (26 - 16 * tTitle).toFixed(2) + 'px',
					}}
				>
					THANKS FOR WATCHING
				</div>
			</div>

			<div
				style={{
					position: 'absolute',
					left: W / 2 - 220 * tRule,
					top: 246,
					width: 440 * tRule,
					height: 1,
					background: 'linear-gradient(90deg, rgba(228,198,140,0), ' + GOLD + ', rgba(228,198,140,0))',
				}}
			/>

			{/* ================= placeholder panels (composited last) ================= */}
			{panel(GX, GY, MW, MH, tMain, 'FEATURED VIDEO', 'm')}
			{panel(RX, GY, RW, RH, tR1, 'WATCH NEXT', 'r1')}
			{panel(RX, GY + RH + GAPY, RW, RH, tR2, 'RECOMMENDED', 'r2')}

			{/* ================= bottom furniture ================= */}
			<div
				style={{
					position: 'absolute',
					left: 0,
					top: 930,
					width: W,
					textAlign: 'center',
					opacity: tSub,
					transform: 'translateY(' + ((1 - tSub) * 16).toFixed(1) + 'px)',
				}}
			>
				<div style={{fontSize: 17, fontWeight: 500, letterSpacing: 6.4, color: DIM}}>
					LIKE &nbsp;&#183;&nbsp; COMMENT &nbsp;&#183;&nbsp; SHARE
				</div>
			</div>

			<div
				style={{
					position: 'absolute',
					left: W / 2 - 132,
					top: 978,
					width: 264,
					height: 54,
					opacity: tPill,
					transform: 'scale(' + (0.9 + 0.1 * tPill).toFixed(3) + ')',
					transformOrigin: '50% 50%',
				}}
			>
				<div
					style={{
						position: 'absolute',
						inset: -12,
						borderRadius: 34,
						background:
							'radial-gradient(60% 70% at 50% 50%, rgba(228,198,140,' + (0.16 + 0.1 * breathe).toFixed(3) + '), rgba(228,198,140,0) 72%)',
						filter: 'blur(10px)',
					}}
				/>
				<div
					style={{
						position: 'absolute',
						inset: 0,
						border: '1.5px solid ' + GOLD,
						borderRadius: 27,
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'center',
						gap: 12,
						background: 'linear-gradient(180deg, rgba(228,198,140,0.1), rgba(228,198,140,0.02))',
					}}
				>
					<svg width={17} height={17} viewBox="0 0 17 17">
						<path d="M2 4.4h13v8.2H2z" fill="none" stroke={GOLD} strokeWidth={1.4} />
						<path d="M7 6.6l4 1.9-4 1.9z" fill={GOLD} />
					</svg>
					<span style={{fontSize: 15, fontWeight: 800, letterSpacing: 4.4, color: GOLD_HI}}>
						SUBSCRIBE
					</span>
				</div>
			</div>

			<div
				style={{
					position: 'absolute',
					left: 84,
					top: 1006,
					fontSize: 12.5,
					fontWeight: 700,
					letterSpacing: 3.6,
					color: GOLD_D,
					opacity: tMeta,
				}}
			>
				
			</div>
			<div
				style={{
					position: 'absolute',
					right: 84,
					top: 1006,
					fontSize: 12.5,
					fontWeight: 700,
					letterSpacing: 3.6,
					color: GOLD_D,
					opacity: tMeta,
					textAlign: 'right',
				}}
			>
				NEW VIDEOS EVERY WEEK
			</div>
			<div
				style={{
					position: 'absolute',
					left: 84,
					top: 62,
					width: 46,
					height: 1,
					background: GOLD_D,
					opacity: tMeta,
				}}
			/>
			<div
				style={{
					position: 'absolute',
					right: 84,
					top: 62,
					width: 46,
					height: 1,
					background: GOLD_D,
					opacity: tMeta,
				}}
			/>
		</AbsoluteFill>
	);
};

export default Motion;
